    bottles.forEach((b) => { outline(b).forEach((p) => sky.push(p)); sky.push(null); });
    skyLen = [];
    let s = 0;
    for (let i = 0; i < sky.length; i++) { if (i && sky[i] && sky[i - 1]) s += Math.hypot(sky[i][0] - sky[i - 1][0], sky[i][1] - sky[i - 1][1]); else if (i) s += 40; skyLen.push(s); }
